<?php
namespace Tests\Feature;
use App\Models\{BookingServis,JenisServis,Servis,User}; use App\Services\{BookingServisService,ServisService}; use Illuminate\Foundation\Testing\DatabaseTransactions; use RuntimeException; use Tests\TestCase;
class ServisStage5ABoundaryTest extends TestCase { use DatabaseTransactions;
 private function user(string $r):User{return User::whereHas('role',fn($q)=>$q->where('nama_role',$r))->firstOrFail();}
 private function service(string $status='diterima'):Servis{$u=$this->user('pelanggan');$v=$u->pelanggan->kendaraan()->create(['merk'=>'QA','model'=>'Boundary','nomor_polisi'=>'BD-'.random_int(1000,9999),'kilometer'=>20000,'status'=>'aktif']);$t=JenisServis::where('status','aktif')->firstOrFail();$b=app(BookingServisService::class)->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$t->id_jenis_servis,now()->addDay()->toDateString(),'11:00',null,null);$b->forceFill(['status'=>$status])->save();return app(ServisService::class)->createFromBooking($b->id_booking_servis,$this->user('petugas')->petugas->id_petugas,20000,null);}
 public function test_admin_can_create_work_order_from_http():void{$u=$this->user('pelanggan');$v=$u->pelanggan->kendaraan()->create(['merk'=>'QA','model'=>'HTTP','nomor_polisi'=>'HT-'.random_int(1000,9999),'kilometer'=>1,'status'=>'aktif']);$t=JenisServis::where('status','aktif')->firstOrFail();$b=app(BookingServisService::class)->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$t->id_jenis_servis,now()->addDay()->toDateString(),'11:00',null,null);$b->forceFill(['status'=>'diterima'])->save();$this->actingAs($this->user('admin'))->post('/admin/servis/from-booking/'.$b->id_booking_servis,['kilometer'=>2])->assertRedirect();$this->assertDatabaseHas('servis',['id_booking_servis'=>$b->id_booking_servis]);}
 public function test_customer_cannot_start_work_order():void{$b=$this->service()->bookingServis;$this->actingAs($this->user('pelanggan'))->post('/pelanggan/servis/from-booking/'.$b->id_booking_servis)->assertNotFound();}
 public function test_inspection_requires_nonempty_diagnosis():void{$s=$this->service();$this->actingAs($this->user('admin'))->post('/admin/servis/'.$s->id_servis.'/inspection',['hasil_pemeriksaan'=>''])->assertSessionHasErrors('hasil_pemeriksaan');}
 public function test_detail_delete_is_scoped_to_parent_service():void{$s=$this->service();app(ServisService::class)->updateInspection($s->id_servis,'Diagnosis',null);$d=app(ServisService::class)->addDetail($s->id_servis,null,'Jasa','10',null);$this->expectException(\Illuminate\Database\Eloquent\ModelNotFoundException::class);app(ServisService::class)->removeDetail($s->id_servis+999,$d->id_detail_servis);}
 public function test_native_walk_in_baseline_remains_readable():void{$s=Servis::whereNull('id_booking_servis')->firstOrFail();$this->assertNull($s->bookingServis);}
 public function test_no_service_delete_route_is_exposed():void{$this->assertFalse(collect(app('router')->getRoutes())->contains(fn($r)=>$r->getName()==='admin.servis.destroy'));}
 public function test_prices_are_not_derived_from_customer_input():void{$s=$this->service();app(ServisService::class)->updateInspection($s->id_servis,'Diagnosis',null);$d=app(ServisService::class)->addDetail($s->id_servis,null,'Jasa','123.45',null);$this->assertSame('123.45',$d->fresh()->biaya);$this->assertSame('0.00',$s->fresh()->total_biaya);}
 public function test_booking_status_does_not_move_to_done_in_stage_5a():void{$s=$this->service();$this->assertSame('diproses',$s->bookingServis->fresh()->status);}
}
